int check(long long n, long long b, int p) {
	while (n) {
		long long r = n % b;
		n /= b;
		for (int i = 1; i < p; ++i) {
			if (n % b != r) return 0;
			n /= b;
		}
	}
	return 1;
}
int main(){
	long long n, sum, pow;
