void Alice() {
    int n; ll s; cin >> n >> s;
    s -= 1;
    vector<bool> special(n + 1, false);
    for (int i = 2; i <= n; i++) special[i] = (s >> (i - 2)) & 1;
    for (int i = 1; i < n; i++) {
        int u, v; cin >> u >> v;
        if (u > v) swap(u, v);
        if (special[u] ^ special[v]) swap(v, u);
        cout << u << ' ' << v << endl;
    }
	return;
}

void Bob() {
    int n; cin >> n;
    vector<vector<pair<int, int>>> g(n + 1, vector<pair<int, int>>());
    for (int i = 1; i < n; i++) {
        int u, v; cin >> u >> v;
        int c = (u > v);
        g[u].push_back({v, c});
        g[v].push_back({u, c});
    }
    vector<bool> special(n + 1, false);
    auto dfs = [&](auto self, int u, int f) -> void {
        for (auto e : g[u]) {
            int v = e.first, c = e.second;
            if (v == f) continue;
            if (c) special[v] = special[u] ^ 1;
            else special[v] = special[u];
            self(self, v, u);
        }
    };
    dfs(dfs, 1, 0);
    ll s = 0;
    for (int i = 2; i <= n; i++) {
        if (special[i]) s |= (1 << (i - 2));
    }
    cout << s + 1 << endl;
}

int main() {
